  <div class="faq">${[S.hfaq[0]].concat(S.find.slice(0,3)).map(f => `<details><summary>${esc(f[0])}</summary><p>${esc(f[1])}${f[3] === "book" ? ` <a class="x-link js-book" href="${D.book}" target="_blank" rel="noopener">${esc(f[2])}</a>` : ""}</p></details>`).join("")}</div>
