  if (!tone) { tone = document.createElement("div"); tone.id = "fdTone"; tone.setAttribute("aria-hidden", "true"); const au = document.getElementById("aura"); (au && au.parentNode ? au.parentNode.insertBefore(tone, au.nextSibling) : document.body.prepend(tone)); }
