function wireFirstDay(){ const root = document.querySelector(".fdo"); if (!root) return; let st = "charcoal"; try { st = localStorage.getItem("esFdTheme") || st; } catch(e) {} fdTheme(st);
  const rm = matchMedia("(prefers-reduced-motion: reduce)").matches;
  const secs = root.querySelectorAll("[data-reveal]");
  if (!rm && "IntersectionObserver" in window) {
    secs.forEach(t => { const kids = t.querySelectorAll("[data-reveal-item]"); if (kids.length) kids.forEach(k => k.style.opacity = "0"); else t.style.opacity = "0"; });
    const io = new IntersectionObserver(es => es.forEach(e => { if (!e.isIntersecting) return; const t = e.target; const kids = t.querySelectorAll("[data-reveal-item]");
      if (kids.length) kids.forEach((k, i) => { k.style.opacity = ""; k.style.animation = "sectionReveal 1s cubic-bezier(.2,0,0,1) " + (0.1 + Math.min(i * 0.12, 0.8)).toFixed(2) + "s both"; });
      else { t.style.opacity = ""; t.style.animation = "sectionReveal 1.05s cubic-bezier(.2,0,0,1) .1s both"; }
      io.unobserve(t); }), { threshold: 0, rootMargin: "0px 0px -24% 0px" });
    secs.forEach(t => io.observe(t));
  }
  const tools = root.querySelectorAll("[data-tool-in]");
  if (rm || !("IntersectionObserver" in window)) { tools.forEach(el => { el.style.opacity = "1"; el.style.transform = "none"; }); return; }
  const tio = new IntersectionObserver(es => es.forEach(e => { if (!e.isIntersecting) return; const el = e.target, i = parseFloat(getComputedStyle(el).getPropertyValue("--i")) || 0;
    const rise = el.dataset.anim === "toolRise", delay = rise ? 0.2 : 0.25 + i * 0.75;
    el.style.animation = (rise ? "toolRise 1.9s cubic-bezier(.16,1,.3,1) " : "toolIn 2.4s cubic-bezier(.16,1,.3,1) ") + delay.toFixed(2) + "s both";
    el.querySelectorAll("[data-snip]").forEach(g => { g.style.animation = g.dataset.snip + " 7s cubic-bezier(.45,0,.25,1) " + (delay + 1.7).toFixed(2) + "s infinite"; });
    tio.unobserve(el); }), { threshold: 0.35 });
  tools.forEach(el => tio.observe(el));
}
