/* FAQ / staff accordions: smooth height animation on open and close, like the services list */
document.addEventListener("click", e => { const sm = e.target.closest(".faq summary, details.st-det > summary"); if (!sm || reduce) return; const d = sm.parentElement; if (d._anim) return; e.preventDefault();
  const ease = "cubic-bezier(.22,.61,.36,1)", start = d.offsetHeight, closing = d.open;
  d.style.overflow = "hidden";
  if (!closing) d.open = true;
  const end = closing ? sm.offsetHeight + (parseFloat(getComputedStyle(d).borderBottomWidth) || 0) : d.offsetHeight;
  const body = [...d.children].filter(c => c !== sm);
  d._anim = d.animate([{ height: start + "px" }, { height: end + "px" }], { duration: closing ? 380 : 480, easing: ease });
  body.forEach(c => c.animate(closing ? [{ opacity: 1, transform: "none" }, { opacity: 0, transform: "translateY(-6px)" }] : [{ opacity: 0, transform: "translateY(-8px)" }, { opacity: 1, transform: "none" }], { duration: closing ? 260 : 460, delay: closing ? 0 : 60, easing: ease, fill: "both" }));
  d._anim.onfinish = d._anim.oncancel = () => { if (closing) d.open = false; d.style.overflow = ""; body.forEach(c => c.getAnimations().forEach(a => a.cancel())); d._anim = null; };
});

